package com.mariageplus.dto.event;

import com.mariageplus.entity.EventDressCode;
import com.mariageplus.util.DressColors;
import com.mariageplus.entity.EventType;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import lombok.Data;

import java.time.LocalDate;
import java.time.LocalTime;

/**
 * Création d'un événement (nouvelle racine unifiée).
 * Le {@code organizationId} est ignoré pour un ORGANISATEUR (périmètre déduit
 * de l'utilisateur connecté) ; il est utilisé uniquement par un SUPER_ADMIN.
 *
 * {@code weddingDetails} est requis si {@code type = WEDDING} et rejeté
 * (400) pour tout autre type (décision D2 du document de conception).
 */
@Data
public class CreateEventRequest {

    @NotBlank(message = "Le nom de l'événement est requis")
    @Size(max = 150, message = "Le nom ne doit pas dépasser 150 caractères")
    private String name;

    @NotNull(message = "Le type d'événement est requis")
    private EventType type;

    @Size(max = 2000, message = "La description ne doit pas dépasser 2000 caractères")
    private String description;

    @Size(max = 2000, message = "Le message d'invitation ne doit pas dépasser 2000 caractères")
    private String message;

    @Pattern(regexp = "STANDARD|ROMANCE|PRESTIGE", message = "Modèle de carte invalide")
    private String invitationCardTemplate;

    private LocalDate eventDate;

    private LocalTime startTime;

    private LocalTime endTime;

    @Size(max = 200, message = "Le nom du lieu ne doit pas dépasser 200 caractères")
    private String venueName;

    @Size(max = 255, message = "L'adresse ne doit pas dépasser 255 caractères")
    private String venueAddress;

    @Size(max = 100, message = "La ville ne doit pas dépasser 100 caractères")
    private String city;

    @Size(max = 100, message = "La commune ne doit pas dépasser 100 caractères")
    private String commune;

    @Size(max = 100, message = "Le pays ne doit pas dépasser 100 caractères")
    private String country;

    @DecimalMin(value = "-90.0", message = "La latitude doit être comprise entre -90 et 90")
    @DecimalMax(value = "90.0", message = "La latitude doit être comprise entre -90 et 90")
    private Double latitude;

    @DecimalMin(value = "-180.0", message = "La longitude doit être comprise entre -180 et 180")
    @DecimalMax(value = "180.0", message = "La longitude doit être comprise entre -180 et 180")
    private Double longitude;

    @Size(max = 1000, message = "L'URL de la carte ne doit pas dépasser 1000 caractères")
    @Pattern(regexp = "(?i)^https?://\\S+$", message = "L'URL de la carte doit commencer par http:// ou https://")
    private String mapUrl;

    /**
     * Couleurs de tenue demandées aux invités (facultatif). Maximum 3 : un pagne
     * peut combiner plusieurs teintes. Liste vide = aucune couleur imposée.
     */
    @Size(max = DressColors.MAX, message = "Vous pouvez demander au maximum 3 couleurs de tenue")
    private java.util.List<EventDressCode> dressColors;

    private Integer displayOrder;

    /** Requis uniquement si type = WEDDING. */
    private WeddingDetailsRequest weddingDetails;

    private Long organizationId;
}

package com.mariageplus.dto.event;

import com.mariageplus.entity.EventDressCode;
import com.mariageplus.util.DressColors;
import jakarta.validation.constraints.Size;
import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Pattern;
import lombok.Data;

import java.time.LocalDate;
import java.time.LocalTime;

/**
 * Modification partielle d'un événement (champs null = inchangés).
 * Si {@code weddingDetails} est fourni, l'événement doit être de type WEDDING.
 */
@Data
public class UpdateEventRequest {

    @Size(max = 150, message = "Le nom ne doit pas dépasser 150 caractères")
    private String name;

    @Size(max = 2000, message = "La description ne doit pas dépasser 2000 caractères")
    private String description;

    @Size(max = 2000, message = "Le message d'invitation ne doit pas dépasser 2000 caractères")
    private String message;

    @Pattern(regexp = "STANDARD|ROMANCE|PRESTIGE", message = "Modèle de carte invalide")
    private String invitationCardTemplate;

    private LocalDate eventDate;

    private LocalTime startTime;

    private LocalTime endTime;

    @Size(max = 200, message = "Le nom du lieu ne doit pas dépasser 200 caractères")
    private String venueName;

    @Size(max = 255, message = "L'adresse ne doit pas dépasser 255 caractères")
    private String venueAddress;

    @Size(max = 100, message = "La ville ne doit pas dépasser 100 caractères")
    private String city;

    @Size(max = 100, message = "La commune ne doit pas dépasser 100 caractères")
    private String commune;

    @Size(max = 100, message = "Le pays ne doit pas dépasser 100 caractères")
    private String country;

    @DecimalMin(value = "-90.0", message = "La latitude doit être comprise entre -90 et 90")
    @DecimalMax(value = "90.0", message = "La latitude doit être comprise entre -90 et 90")
    private Double latitude;

    @DecimalMin(value = "-180.0", message = "La longitude doit être comprise entre -180 et 180")
    @DecimalMax(value = "180.0", message = "La longitude doit être comprise entre -180 et 180")
    private Double longitude;

    @Size(max = 1000, message = "L'URL de la carte ne doit pas dépasser 1000 caractères")
    @Pattern(regexp = "(?i)^https?://\\S+$", message = "L'URL de la carte doit commencer par http:// ou https://")
    private String mapUrl;

    /**
     * Couleurs de tenue demandées aux invités (facultatif). Maximum 3. Une liste
     * vide explicite remet à zéro le vestiaire.
     */
    @Size(max = DressColors.MAX, message = "Vous pouvez demander au maximum 3 couleurs de tenue")
    private java.util.List<EventDressCode> dressColors;

    private Integer displayOrder;

    private Boolean active;

    private WeddingDetailsRequest weddingDetails;
}

package com.mariageplus.dto.event;

import lombok.Builder;
import lombok.Data;

import java.time.LocalDate;
import java.time.LocalTime;
import java.util.List;

/**
 * Réponse d'un événement : socle commun + {@code weddingDetails} si le type
 * est WEDDING (sinon null) + les sessions (sous-étapes) de l'événement.
 */
@Data
@Builder
public class EventResponse {
    private Long id;
    private String name;
    private String type;
    private String description;
    private String message;
    private String invitationCardTemplate;

    private LocalDate eventDate;
    private LocalTime startTime;
    private LocalTime endTime;
    private String venueName;
    private String venueAddress;
    private String city;
    private String commune;
    private String country;
    private Double latitude;
    private Double longitude;
    private String mapUrl;
    private String status;
    /** Codes des couleurs demandées aux invités (max 3), dans l'ordre saisi. */
    private java.util.List<String> dressColors;
    /** Une photo du pagne / tissu à porter est-elle jointe à l'événement ? */
    private boolean hasDressImage;
    private Integer displayOrder;
    private Boolean active;
    private Long organizationId;
    private Boolean hasImage;
    /** Nombre d'invités enregistrés pour cet événement. */
    private long guestCount;
    private WeddingDetailsResponse weddingDetails;
    private List<EventSessionResponse> sessions;
}

package com.mariageplus.dto.invitation;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Réponse publique minimale, utilisée par l'accès par publicToken.
 * Ne contient aucune donnée administrative interne.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class PublicInvitationResponse {

    private String invitationCardTemplate;

    private String guestFirstName;
    private String guestLastName;

    /** Nom du couple affiché (« Groom & Bride ») — infos mariage minimales pour l'invité. */
    private String weddingDisplayName;

    // Visuel & message (depuis Wedding)
    private String couplePhotoUrl;
    private String groomPhotoUrl;
    private String bridePhotoUrl;
    /** Photo de couverture commune à tous les types d'événements. */
    private String eventPhotoUrl;
    private String message;

    // Événement principal (date / heure / lieu formatés en français)
    private String eventName;
    private String eventDate;
    private String eventStartTime;
    private String eventVenue;

    /** Coordonnées et lien cartographique du lieu principal, si renseignés. */
    private Double latitude;
    private Double longitude;
    private String mapUrl;

    /**
     * Vestiaire de l'invité : couleurs demandées (maximum 3) avec libellé français
     * et couleur d'aperçu, plus la photo du pagne / tissu quand l'organisateur en
     * a joint une (mariages coutumiers). Vide / null si aucune consigne.
     */
    private java.util.List<com.mariageplus.dto.event.DressCodeOption> dressColors;
    private String dressImageUrl;

    /** Maximum de participants accepté : 1 + allowedCompanions (résolu côté backend). */
    private Integer maxAccepted;

    private String status;
    private String rsvpStatus;
    private Integer rsvpNumberOfAttendees;
    private String rsvpDrinkChoice;

    /** Choix multiples de boissons du RSVP (pré-remplissage du formulaire invité). */
    private java.util.List<String> rsvpDrinkChoices;

    /** Message libre laissé par l'invité au moment du RSVP (pré-remplissage, additif). */
    private String rsvpNote;

    /** Token public de l'invitation, nécessaire pour afficher le QR code côté front. */
    private String publicToken;

    /** Programme de la journée : sessions actives de l'événement, triées (additif — peut être vide). */
    private java.util.List<PublicEventSessionResponse> sessions;
}

package com.mariageplus.entity;

import jakarta.persistence.*;
import lombok.*;

/**
 * Événement : nouvelle racine métier unifiée (Phase 1 — coexistence avec
 * {@link Wedding}). Tous les types (mariage, collation, anniversaire...)
 * partagent ce socle commun ; seul le type WEDDING dispose d'une fiche de
 * détails dédiée ({@link WeddingDetails}).
 *
 * L'isolation est portée par {@code organizationId} et vérifiée côté service
 * via {@code OrganizationMember}. {@code createdAt}/{@code updatedAt}/
 * {@code deletedAt} sont hérités de {@link BaseEntity}.
 */
@Entity
@Table(name = "events", indexes = {
        @Index(name = "idx_events_org", columnList = "organization_id"),
        @Index(name = "idx_events_org_date", columnList = "organization_id, event_date"),
        @Index(name = "idx_events_org_type", columnList = "organization_id, type")
})
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Event extends BaseEntity {

    @Column(name = "organization_id", nullable = false)
    private Long organizationId;

    @Column(nullable = false, length = 150)
    private String name;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 30)
    private EventType type;

    @Column(length = 2000)
    private String description;

    /** Petit mot personnalisé de l'organisateur, affiché dans l'email et la page invité. */
    @Column(length = 2000)
    private String message;

    @Builder.Default
    @Column(name = "invitation_card_template", nullable = false, length = 20)
    private String invitationCardTemplate = "STANDARD";

    @Column(name = "event_date")
    private java.time.LocalDate eventDate;

    @Column(name = "start_time")
    private java.time.LocalTime startTime;

    @Column(name = "end_time")
    private java.time.LocalTime endTime;

    @Column(name = "venue_name", length = 200)
    private String venueName;

    @Column(name = "venue_address", length = 255)
    private String venueAddress;

    @Column(length = 100)
    private String city;

    @Column(length = 100)
    private String commune;

    @Column(length = 100)
    private String country;

    private Double latitude;

    private Double longitude;

    @Column(name = "map_url", length = 1000)
    private String mapUrl;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 30)
    @Builder.Default
    private EventStatus status = EventStatus.DRAFT;

    /**
     * Couleurs de tenue demandées aux invités : CSV de codes enum
     * (ex : "BLACK,IVORY,WHITE"), maximum 3 (cf. DressColors.MAX). Null si
     * aucune couleur imposée.
     */
    @Column(name = "dress_colors", length = 60)
    private String dressColors;

    /**
     * Clé objet S3 de la photo du pagne / tissu à porter. Les mariages
     * coutumiers distribuent un tissu que les invités doivent coudre : sans
     * photo, la consigne de couleur est incompréhensible.
     */
    @Column(name = "dress_image_key", length = 255)
    private String dressImageKey;

    @Column(name = "display_order")
    private Integer displayOrder;

    @Builder.Default
    @Column(nullable = false)
    private boolean active = true;

    @Column(name = "created_by")
    private Long createdBy;

    @Column(name = "updated_by")
    private Long updatedBy;

    /** Photo de couverture : clé objet S3 (prioritaire) / fallback en base. */
    @Column(name = "image_key", length = 500)
    private String imageKey;

    /** Repli en base de la photo du pagne quand le stockage objet est désactivé. */
    @Column(name = "dress_image")
    private byte[] dressImage;

    @Column(name = "image")
    private byte[] image;
}

package com.mariageplus.service;

import com.mariageplus.dto.PageResponse;
import com.mariageplus.dto.event.CreateEventRequest;
import com.mariageplus.dto.event.EventResponse;
import com.mariageplus.dto.event.UpdateEventRequest;
import com.mariageplus.dto.event.UpdateEventStatusRequest;
import com.mariageplus.dto.event.WeddingDetailsRequest;
import com.mariageplus.entity.Event;
import com.mariageplus.entity.EventSession;
import com.mariageplus.entity.EventStatus;
import com.mariageplus.entity.EventType;
import com.mariageplus.entity.WeddingDetails;
import com.mariageplus.exception.ForbiddenException;
import com.mariageplus.exception.ResourceNotFoundException;
import com.mariageplus.mapper.EventMapper;
import com.mariageplus.repository.EventRepository;
import com.mariageplus.repository.EventSessionRepository;
import com.mariageplus.repository.GuestRepository;
import com.mariageplus.repository.WeddingDetailsRepository;
import com.mariageplus.security.SecurityUtils;
import com.mariageplus.util.DressColors;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageImpl;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Pageable;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalTime;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * Module événements (nouvelle racine métier unifiée — Phase 1, coexistence
 * avec {@link WeddingService}).
 *
 * Règles :
 * - Le type WEDDING exige {@code weddingDetails} ; tout autre type le rejette (400).
 * - L'isolation par organisation est portée par {@code Event.organizationId}.
 * - Permissions réutilisées du socle existant (EVENT_*, WEDDING_PUBLISH...).
 */
@Service
@RequiredArgsConstructor
public class EventService {

    private final EventRepository eventRepository;
    private final OrganizationSettingsService organizationSettingsService;
    private final WeddingDetailsRepository weddingDetailsRepository;
    private final EventSessionRepository eventSessionRepository;
    private final GuestRepository guestRepository;
    private final EventMapper eventMapper;
    private final SecurityUtils securityUtils;
    private final StorageService storageService;
    private final AuditService auditService;

    @Transactional
    public EventResponse create(CreateEventRequest request) {
        securityUtils.assertPermission("EVENT_CREATE");
        validateWeddingDetailsPresence(request.getType(), request.getWeddingDetails());
        Long organizationId = resolveOrganizationForCreate(request.getOrganizationId());
        // Réglage par organisation (hérite du global) : seuls les SUPER_ADMIN
        // peuvent créer quand la création est interdite à l'organisation.
        if (!securityUtils.isSuperAdmin() && !organizationSettingsService.isEventCreationAllowed(organizationId)) {
            throw new ForbiddenException(
                    "La création d'événements est désactivée pour votre organisation par l'administrateur de la plateforme");
        }
        Long userId = securityUtils.getCurrentUserId();

        Event event = Event.builder()
                .organizationId(organizationId)
                .name(request.getName())
                .type(request.getType())
                .description(request.getDescription())
                .invitationCardTemplate(request.getInvitationCardTemplate() == null ? "STANDARD" : request.getInvitationCardTemplate())
                .message(request.getMessage())
                .eventDate(request.getEventDate())
                .startTime(request.getStartTime())
                .endTime(request.getEndTime())
                .venueName(request.getVenueName())
                .venueAddress(request.getVenueAddress())
                .city(request.getCity())
                .commune(request.getCommune())
                .country(request.getCountry())
                .latitude(request.getLatitude())
                .longitude(request.getLongitude())
                .mapUrl(request.getMapUrl())
                .status(EventStatus.DRAFT)
                .dressColors(DressColors.encode(request.getDressColors()))
                .displayOrder(request.getDisplayOrder())
                .active(true)
                .createdBy(userId)
                .updatedBy(userId)
                .build();
        validateTimes(event.getStartTime(), event.getEndTime());

        Event saved = eventRepository.save(event);

        if (request.getType() == EventType.WEDDING) {
            WeddingDetails details = WeddingDetails.builder()
                    .eventId(saved.getId())
                    .groomFirstName(request.getWeddingDetails().getGroomFirstName())
                    .groomLastName(request.getWeddingDetails().getGroomLastName())
                    .brideFirstName(request.getWeddingDetails().getBrideFirstName())
                    .brideLastName(request.getWeddingDetails().getBrideLastName())
                    .groomPhotoUrl(request.getWeddingDetails().getGroomPhotoUrl())
                    .bridePhotoUrl(request.getWeddingDetails().getBridePhotoUrl())
                    .couplePhotoUrl(request.getWeddingDetails().getCouplePhotoUrl())
                    .welcomeMessage(request.getWeddingDetails().getWelcomeMessage())
                    .build();
            weddingDetailsRepository.save(details);
        }

        auditService.record("EVENT_CREATE", saved.getId(), "Event", userId, organizationId,
                "Création de l'événement '" + saved.getName() + "' (" + saved.getType() + ")");
        return loadFullResponse(saved);
    }

    public EventResponse getById(Long id) {
        securityUtils.assertPermission("EVENT_VIEW");
        Event event = loadInOrgScope(id);
        return loadFullResponse(event);
    }

    public PageResponse<EventResponse> list(int page, int size, String sortBy, String sortDir, EventType type,
            Long organizationIdFilter) {
        securityUtils.assertPermission("EVENT_VIEW");
        Sort sort = "desc".equalsIgnoreCase(sortDir) ? Sort.by(sortBy).descending() : Sort.by(sortBy).ascending();
        Pageable pageable = PageRequest.of(page, size, sort);

        Page<Event> eventPage;
        if (securityUtils.isSuperAdmin()) {
            if (organizationIdFilter != null) {
                // Console SUPER_ADMIN : événements d'une organisation précise
                // (le filtre est ignoré pour les autres rôles, déjà scopés).
                eventPage = (type == null)
                        ? eventRepository.findByOrganizationId(organizationIdFilter, pageable)
                        : eventRepository.findByOrganizationIdAndType(organizationIdFilter, type, pageable);
            } else {
                eventPage = (type == null)
                        ? eventRepository.findAll(pageable)
                        : eventRepository.findByType(type, pageable);
            }
        } else if (securityUtils.isAgentRole()) {
            // Scoping agent : GESTIONNAIRE_INVITES / AGENT_ACCUEIL ne voient QUE les
            // événements qui leur sont assignés (weddingIds), pas toute l'organisation.
            List<Long> scopedIds = securityUtils.getCurrentWeddingIds();
            if (scopedIds.isEmpty()) {
                eventPage = new PageImpl<>(List.of(), pageable, 0);
            } else {
                Long organizationId = securityUtils.requireOrganizationId();
                eventPage = (type == null)
                        ? eventRepository.findByOrganizationIdAndIdIn(organizationId, scopedIds, pageable)
                        : eventRepository.findByOrganizationIdAndTypeAndIdIn(organizationId, type, scopedIds, pageable);
            }
        } else {
            Long organizationId = securityUtils.requireOrganizationId();
            eventPage = (type == null)
                    ? eventRepository.findByOrganizationId(organizationId, pageable)
                    : eventRepository.findByOrganizationIdAndType(organizationId, type, pageable);
        }

        List<Event> events = eventPage.getContent();
        Map<Long, Long> guestCounts = loadGuestCounts(events);
        List<EventResponse> content = events.stream()
                .map(event -> loadFullResponse(event, guestCounts.getOrDefault(event.getId(), 0L)))
                .collect(Collectors.toList());
        return PageResponse.of(content, eventPage);
    }

    @Transactional
    public EventResponse update(Long id, UpdateEventRequest request) {
        securityUtils.assertPermission("EVENT_UPDATE");
        Event event = loadInOrgScope(id);
        if (request.getWeddingDetails() != null && event.getType() != EventType.WEDDING) {
            throw new IllegalArgumentException(
                    "weddingDetails n'est autorisé que pour un événement de type WEDDING");
        }
        applyUpdate(event, request);
        validateTimes(event.getStartTime(), event.getEndTime());
        event.setUpdatedBy(securityUtils.getCurrentUserId());

        Event saved = eventRepository.save(event);

        if (request.getWeddingDetails() != null) {
            upsertWeddingDetails(saved.getId(), request.getWeddingDetails());
        }

        auditService.record("EVENT_UPDATE", saved.getId(), "Event",
                securityUtils.getCurrentUserId(), saved.getOrganizationId(), "Modification de l'événement");
        return loadFullResponse(saved);
    }

    private final OrganizationService organizationService;

    @Transactional
    public EventResponse updateStatus(Long id, UpdateEventStatusRequest request) {
        EventStatus target = parseStatus(request.getStatus());
        securityUtils.assertPermission(permissionForStatus(target));

        Event event = loadInOrgScope(id);
        if (!event.getStatus().canTransitionTo(target)) {
            throw new IllegalArgumentException("Transition de statut invalide : "
                    + event.getStatus() + " → " + target);
        }
        EventStatus previous = event.getStatus();
        event.setStatus(target);
        event.setUpdatedBy(securityUtils.getCurrentUserId());
        Event saved = eventRepository.save(event);
        auditService.record("EVENT_STATUS", saved.getId(), "Event",
                securityUtils.getCurrentUserId(), saved.getOrganizationId(),
                "Changement de statut : " + previous + " → " + target);
        return loadFullResponse(saved);
    }

    /**
     * Suppression logique (soft-delete), même stratégie que les mariages.
     */
    @Transactional
    public void delete(Long id) {
        securityUtils.assertPermission("EVENT_DELETE");
        Event event = loadInOrgScope(id);
        event.setUpdatedBy(securityUtils.getCurrentUserId());
        event.softDelete();
        eventRepository.save(event);
        auditService.record("EVENT_DELETE", id, "Event",
                securityUtils.getCurrentUserId(), event.getOrganizationId(), "Suppression logique de l'événement");
    }

    /**
     * Charge l'événement ET vérifie qu'il appartient au périmètre autorisé.
     * Réutilisée par le module sessions pour centraliser le contrôle d'accès.
     */
    public Event loadInOrgScope(Long id) {
        Event event = eventRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Événement non trouvé avec l'ID: " + id));
        securityUtils.assertOrganizationAccess(event.getOrganizationId());
        // Scoping agent : GESTIONNAIRE_INVITES / AGENT_ACCUEIL n'accèdent qu'aux
        // événements qui leur sont assignés (hérité de l'ancien WeddingService).
        securityUtils.assertWeddingAccess(event.getId());
        return event;
    }

    /**
     * Construit la réponse complète : socle + weddingDetails (si WEDDING) + sessions.
     */
    private EventResponse loadFullResponse(Event event) {
        return loadFullResponse(event, guestRepository.countByWeddingId(event.getId()));
    }

    private EventResponse loadFullResponse(Event event, long guestCount) {
        WeddingDetails details = event.getType() == EventType.WEDDING
                ? weddingDetailsRepository.findByEventId(event.getId()).orElse(null)
                : null;
        List<EventSession> sessions = eventSessionRepository.findByEventId(event.getId());
        EventResponse response = eventMapper.toResponse(event, details, sessions);
        response.setGuestCount(guestCount);
        return response;
    }

    private Map<Long, Long> loadGuestCounts(List<Event> events) {
        if (events.isEmpty()) {
            return Map.of();
        }
        List<Long> eventIds = events.stream().map(Event::getId).toList();
        Map<Long, Long> counts = new HashMap<>();
        guestRepository.countByWeddingIds(eventIds)
                .forEach(row -> counts.put(row.getWeddingId(), row.getGuestCount()));
        return counts;
    }

    /** Taille maximale de la photo d'événement (2 Mo). */
    private static final int IMAGE_MAX_BYTES = 2 * 1024 * 1024;

    /** Upload / remplace la photo de couverture de l'événement. */
    @Transactional
    public void setImage(Long id, byte[] image) {
        securityUtils.assertPermission("EVENT_UPDATE");
        if (image == null || image.length == 0) {
            throw new IllegalArgumentException("Fichier image vide ou manquant");
        }
        if (image.length > IMAGE_MAX_BYTES) {
            throw new IllegalArgumentException("Image trop volumineuse (max 2 Mo)");
        }
        if (!isSupportedImage(image)) {
            throw new IllegalArgumentException("Format d'image non supporté (JPEG, PNG, GIF ou WebP attendu)");
        }
        Event event = loadInOrgScope(id);
        if (storageService.isEnabled()) {
            if (event.getImageKey() != null && !event.getImageKey().isBlank()) {
                storageService.delete(event.getImageKey());
            }
            String key = "events/" + id + "/" + System.currentTimeMillis() + extensionOf(image);
            storageService.upload(key, image, contentTypeOf(image));
            event.setImageKey(key);
            event.setImage(null);
        } else {
            event.setImage(image);
        }
        event.setUpdatedBy(securityUtils.getCurrentUserId());
        eventRepository.save(event);
        auditService.record("EVENT_UPDATE", id, "Event",
                securityUtils.getCurrentUserId(), event.getOrganizationId(), "Mise à jour de la photo de l'événement");
    }

